package com.jobproof.modules.aigateway.application;
import com.jobproof.modules.aigateway.domain.AiGatewayModels.Channel; import java.util.*; import java.util.random.RandomGenerator;
public final class WeightedChannelRouter {private final RandomGenerator random;public WeightedChannelRouter(RandomGenerator r){random=r;}public List<Channel> order(List<Channel> channels){List<Channel> left=new ArrayList<>(channels.stream().filter(Channel::enabled).toList()),out=new ArrayList<>();while(!left.isEmpty()){int best=left.stream().map(Channel::healthPriority).min(Comparator.naturalOrder()).orElseThrow();List<Channel> tier=left.stream().filter(c->c.healthPriority()==best).toList();int total=tier.stream().mapToInt(c->Math.max(1,c.weight())).sum(),ticket=random.nextInt(total);Channel picked=tier.get(0);for(Channel c:tier){ticket-=Math.max(1,c.weight());if(ticket<0){picked=c;break;}}out.add(picked);left.remove(picked);}return List.copyOf(out);}}